//! Passive Text children preserve native identity, records and live ranges.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<!--root--><body><noscript id=host>held</noscript><button id=button><noscript id=guard>guarded</noscript></button><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-text-ranges.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,code:&str)->String{let source=format!("var caughtFailure=null;try{{{code}}}catch(e){{caughtFailure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let value=p.runtime.execute("caughtFailure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();let Value::String(message)=value else{panic!("Expected an actual native refusal: {value:?}")};message}}}




#[test]
fn range_fragment_passive_content_noscript_literal_identity_clone_and_connection(){
 let(mut d,mut f,mut p)=fixture();let controls=f.controls.len();run(&mut d,&mut f,&mut p,r##"
var r=document.createRange(),out=document.getElementById('out'),watch=new MutationObserver(function(){});r.selectNodeContents(out);watch.observe(out,{childList:true});var raw='<style>#out{color:red}</style><img id=fake src=missing><script>window.bad=1;</script>&amp;',fragment=r.createContextualFragment('<noscript id=passive>'+raw+'</noscript>'),host=fragment.firstChild,text=host.firstChild;if(fragment.ownerDocument!==document||host.ownerDocument!==document||host.namespaceURI!=='http://www.w3.org/1999/xhtml'||host.childNodes.length!==1||text.nodeType!==3||text.data!==raw||host.textContent!==raw||host.parentNode!==fragment||host.isConnected||document.getElementById('fake')!==null||document.querySelectorAll('script').length||window.bad!==undefined||watch.takeRecords().length||out.textContent!=='Real'||r.endOffset!==1)throw 'actual passive contextual host';var copy=host.cloneNode(true);if(copy===host||copy.firstChild===text||copy.textContent!==raw||copy.ownerDocument!==document)throw 'actual passive producer clone';out.appendChild(fragment);var rs=watch.takeRecords();if(fragment.firstChild!==null||document.getElementById('passive')!==host||!host.isConnected||host.firstChild!==text||rs.length!==1||rs[0].addedNodes[0]!==host||document.getElementById('fake')!==null)throw 'literal passive connection';text.appendData('\udfff\ud800');if(text.data!==raw+'\udfff\ud800'||host.childNodes.length!==1)throw 'exact native Text after production';out.removeChild(host);if(host.firstChild!==text||text.parentNode!==host||host.isConnected)throw 'passive retirement';
"##);assert_eq!(f.controls.len(),controls);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn range_fragment_passive_content_svg_namespace_attributes_copy_and_connection(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r##"
var r=document.createRange(),out=document.getElementById('out'),watch=new MutationObserver(function(){});r.selectNodeContents(out);watch.observe(out,{childList:true});var ns='http://www.w3.org/2000/svg',xn='http://www.w3.org/2000/xmlns/',fragment=r.createContextualFragment('<svg id=vector xmlns="http://www.w3.org/2000/svg" width=20 height=20 viewBox="0 0 20 20"><g><rect id=shape width=20 height=20 fill="#e03040"/></g></svg>'),svg=fragment.firstChild,rect=svg.firstChild.firstChild;if(!(svg instanceof SVGElement)||svg.namespaceURI!==ns||rect.namespaceURI!==ns||svg.localName!=='svg'||rect.localName!=='rect'||svg.ownerDocument!==document||rect.ownerDocument!==document||svg.getAttribute('viewBox')!=='0 0 20 20'||svg.getAttribute('viewbox')!==null||svg.getAttributeNS(xn,'xmlns')!==ns||rect.getAttribute('fill')!=='#e03040'||svg.parentNode!==fragment||svg.isConnected||document.getElementById('vector')!==null||watch.takeRecords().length||out.textContent!=='Real')throw 'genuine namespace and adjusted attributes';var copied=svg.cloneNode(true);if(copied===svg||copied.firstChild.firstChild===rect||copied.namespaceURI!==ns||copied.firstChild.firstChild.namespaceURI!==ns||copied.ownerDocument!==document)throw 'independent supported SVG copy';out.appendChild(fragment);var rs=watch.takeRecords();if(fragment.firstChild!==null||document.getElementById('shape')!==rect||rect.ownerDocument!==document||!svg.isConnected||rs.length!==1||rs[0].addedNodes[0]!==svg)throw 'actual SVG connection';rect.setAttribute('fill','#40a020');if(rect.getAttribute('fill')!=='#40a020'||copied.firstChild.firstChild.getAttribute('fill')!=='#e03040')throw 'native SVG mutation isolation';
var local=r.createContextualFragment('<svg xmlns:xlink="http://www.w3.org/1999/xlink"><defs><path id=owned d="M0 0 H20 V20 H0 Z"/></defs><use xlink:href="#owned"/></svg>'),use=local.firstChild.lastChild;if(use.namespaceURI!==ns||use.getAttributeNS('http://www.w3.org/1999/xlink','href')!=='#owned'||use.ownerDocument!==document||local.firstChild.firstChild.firstChild.localName!=='path'||watch.takeRecords().length)throw 'genuine local SVG reference and namespace';

"##);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn range_fragment_passive_content_disabled_parse_text_and_rich_fallback_guard(){
 let mut d=crate::html::parse_loaded_document_with_scripting("<body><p id=out>Real</p>",false,&||Ok(())).unwrap();assert!(!d.scripting_enabled);let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);assert!(!d.scripting_enabled);
 // Direct native calls in this harness need admission that disabled-page
 // startup intentionally skips. The parsed scripting flag stays false.
 p.state.node_limit=d.nodes.len().saturating_add(p.state.limits.host.extra_nodes);
 p.state.retained=document_bytes(&d);p.state.retained_limit=p.state.retained.saturating_add(p.state.limits.host.retained_bytes);
 run(&mut d,&mut f,&mut p,"var r=document.createRange();r.selectNodeContents(document.getElementById('out'));var fragment=r.createContextualFragment('<noscript id=passive>A&amp;B</noscript>');if(fragment.firstChild.firstChild.data!=='A&B'||fragment.firstChild.childNodes.length!==1)throw 'actual disabled captured parser mode';");let before=format!("{:?}",d.nodes);p.begin_job();let e=refusal(&mut d,&mut f,&mut p,"r.createContextualFragment('<noscript><span>fallback</span></noscript>');");assert!(!e.is_empty());assert_eq!(format!("{:?}",d.nodes),before);
}
#[test]
fn range_fragment_passive_content_resource_and_quota_refusal_no_prefix_recovery(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var r=document.createRange(),out=document.getElementById('out'),watch=new MutationObserver(function(){});r.selectNodeContents(out);watch.observe(out,{childList:true});");let before=format!("{:?}",d.nodes);let controls=f.controls.len();let commits=p.state.dom_commits;
 for code in ["r.createContextualFragment('<span>prefix</span><svg onload=bad><rect width=1 height=1/></svg>');","r.createContextualFragment('<svg><use href=https://remote.test/a.svg#shape /></svg>');","r.createContextualFragment('<svg><foreignObject><div>bad</div></foreignObject></svg>');","r.createContextualFragment('<noscript onclick=bad>text</noscript>');","r.createContextualFragment('<noscript is=custom-host>text</noscript>');"]{p.begin_job();let e=refusal(&mut d,&mut f,&mut p,code);assert!(!e.is_empty());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(f.controls.len(),controls);assert_eq!(p.state.dom_commits,commits);}
 let retained=p.state.retained_limit;let nodes=p.state.node_limit;for mode in 0..4{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.node_limit=d.nodes.len()};let e=refusal(&mut d,&mut f,&mut p,"r.createContextualFragment('<noscript>literal</noscript><svg width=20 height=20><rect width=20 height=20 fill=red /></svg>');").to_ascii_lowercase();assert!(e.contains("limit")||e.contains("allowance")||e.contains("storage"),"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(f.controls.len(),controls);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=retained;p.state.node_limit=nodes;}
 p.begin_job();run(&mut d,&mut f,&mut p,"if(out.textContent!=='Real'||r.startContainer!==out||r.endOffset!==1||watch.takeRecords().length)throw 'source preserved';var fresh=r.createContextualFragment('<noscript>fresh</noscript><svg><rect width=1 height=1 /></svg>');if(fresh.childNodes.length!==2||fresh.firstChild.firstChild.data!=='fresh'||fresh.lastChild.namespaceURI!=='http://www.w3.org/2000/svg')throw 'fresh passive recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
